// LCA OF BINARY TREE (general) — O(n) time, O(h) space
function lowestCommonAncestor(root, p, q) {
    if (!root) return null;           // base: empty tree
    if (root === p || root === q) return root; // found p or q: return it

    const left  = lowestCommonAncestor(root.left,  p, q);
    const right = lowestCommonAncestor(root.right, p, q);

    // Both subtrees returned non-null: root is the split point = LCA
    if (left && right) return root;
    // Only one subtree found both nodes: propagate that result upward
    return left || right;
}
// TRACE on tree [3,5,1,6,2,0,8] finding LCA(5, 1):
// root=3: recurse left and right
//   left subtree (5): root===p -> return node(5)
//   right subtree (1): root===q -> return node(1)
// left=node(5), right=node(1): both non-null -> return root=node(3)
// LCA = 3

// TRACE finding LCA(5, 4) where 4 is left child of 2 which is right child of 5:
// root=3: recurse
//   left subtree root=5: root===p -> return node(5) immediately
//   (right subtree of 3 does NOT contain 4 in this tree)
// left=node(5), right=null -> return node(5)
// LCA = 5 (5 is ancestor of 4)

// LCA OF BST — O(h) by exploiting BST invariant
function lowestCommonAncestorBST(root, p, q) {
    if (!root) return null;
    // Both nodes smaller: LCA is in left subtree
    if (p.val < root.val && q.val < root.val)
        return lowestCommonAncestorBST(root.left, p, q);
    // Both nodes larger: LCA is in right subtree
    if (p.val > root.val && q.val > root.val)
        return lowestCommonAncestorBST(root.right, p, q);
    // Split point: one <= root <= other, root is the LCA
    return root;
}

// ITERATIVE BST LCA — O(h) time, O(1) space
function lowestCommonAncestorBSTIterative(root, p, q) {
    let curr = root;
    while (curr) {
        if (p.val < curr.val && q.val < curr.val) curr = curr.left;
        else if (p.val > curr.val && q.val > curr.val) curr = curr.right;
        else return curr; // split point
    }
    return null;
}

