// BFS APPROACH — last node per level
function rightSideViewBFS(root) {
    if (!root) return [];
    const result = [];
    const queue = [root];
    while (queue.length) {
        const levelSize = queue.length;
        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift();
            if (i === levelSize - 1) result.push(node.val); // last in level
            if (node.left)  queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
    }
    return result;
}

// DFS APPROACH — right-first preorder, first visit per depth
function rightSideViewDFS(root) {
    const result = [];
    function dfs(node, depth) {
        if (!node) return;
        // First time visiting this depth: this is the rightmost node
        if (depth === result.length) result.push(node.val);
        dfs(node.right, depth + 1); // right first: ensures rightmost seen first
        dfs(node.left,  depth + 1);
    }
    dfs(root, 0);
    return result;
}

// Tree:      1
