// DFS: depth=0 result=[1]. right=3:depth=1 result=[1,3].
//      right=4:depth=2 result=[1,3,4]. left=null.
//      left=2:depth=1 result.length=2!=1 skip.
//      right=5:depth=2 result.length=3!=2 skip.
// Both return [1, 3, 4]

// LEFT SIDE VIEW — symmetric: visit left first, same pattern
function leftSideViewDFS(root) {
    const result = [];
    function dfs(node, depth) {
        if (!node) return;
        if (depth === result.length) result.push(node.val);
        dfs(node.left,  depth + 1); // left first
        dfs(node.right, depth + 1);
    }
    dfs(root, 0);
    return result;
}

