// COUNT GOOD NODES — O(n) top-down DFS
function goodNodes(root) {
    function dfs(node, maxSoFar) {
        if (!node) return 0;
        // Is this node good? Its value >= max on path from root
        const isGood = node.val >= maxSoFar ? 1 : 0;
        // Update maxSoFar for children
        const newMax = Math.max(maxSoFar, node.val);
        // Count good nodes in both subtrees
        return isGood +
               dfs(node.left,  newMax) +
               dfs(node.right, newMax);
    }
    return dfs(root, -Infinity); // root always good: -Infinity < any value
}

// TRACE on tree [3, 1, 4, 3, null, 1, 5]:
//        3
//       / \
//      1   4
//     /   / \
//    3   1   5
// dfs(3, -Inf): 3>=-Inf good=1. newMax=3.
//   dfs(1, 3):  1<3 good=0. newMax=3.
//     dfs(3, 3): 3>=3 good=1. children null. return 1.
//   return 0+1+0 = 1
//   dfs(4, 3): 4>=3 good=1. newMax=4.
//     dfs(1, 4): 1<4 good=0. return 0.
//     dfs(5, 4): 5>=4 good=1. return 1.
//   return 1+0+1 = 2
// return 1+1+2 = 4
// Answer: 4 good nodes (3, 3, 4, 5)

// GENERALISATION: any path property uses the same pattern
// Replace maxSoFar with any accumulated path property:
// - Count nodes where value > all ancestors: same pattern
// - Count nodes where value is prime AND path contains no even: same structure
// - Find deepest node satisfying a cumulative path condition: same structure
function countNodesWithPathProperty(root, propertyValue, updateFn, checkFn) {
    function dfs(node, acc) {
        if (!node) return 0;
        const count = checkFn(node.val, acc) ? 1 : 0;
        const newAcc = updateFn(acc, node.val);
        return count + dfs(node.left, newAcc) + dfs(node.right, newAcc);
    }
    return dfs(root, propertyValue);
}
