// SERIALIZE — preorder DFS with null markers
function serialize(root) {
    const parts = [];
    function dfs(node) {
        if (!node) { parts.push('null'); return; }
        parts.push(String(node.val));
        dfs(node.left);
        dfs(node.right);
    }
    dfs(root);
    return parts.join(',');
}
// Tree:  1
//       / \
//      2   3
//         / \
//        4   5
// Serialized: '1,2,null,null,3,4,null,null,5,null,null'

// DESERIALIZE — consume preorder tokens via queue
function deserialize(data) {
    const vals = data.split(',');
    let i = 0; // pointer into vals array

    function build() {
        if (vals[i] === 'null') { i++; return null; }
        const node = new TreeNode(Number(vals[i++]));
        node.left  = build(); // left child built from next tokens
        node.right = build(); // right child built from tokens after left subtree
        return node;
    }
    return build();
}

// VERIFY round-trip
const original = new TreeNode(1,
    new TreeNode(2),
    new TreeNode(3, new TreeNode(4), new TreeNode(5))
);
const serialised = serialize(original);
console.log(serialised); // '1,2,null,null,3,4,null,null,5,null,null'
const reconstructed = deserialize(serialised);
console.log(serialize(reconstructed) === serialised); // true

// WHY NULL MARKERS ARE NECESSARY
// Without nulls: [1,2,3] could represent:
//   1       OR   1      OR    1
//  /             \            /\
// 2               2          2  3
//  \
//   3
// With nulls: '1,2,null,null,3,null,null' uniquely means:
//   1
//  / \
// 2   3

