// BINARY TREE MAXIMUM PATH SUM — O(n) single postorder pass
function maxPathSum(root) {
    let globalMax = -Infinity; // handles all-negative trees

    function gain(node) {
        if (!node) return 0;

        // Maximum gain from going left or right (ignore negative contributions)
        const leftGain  = Math.max(0, gain(node.left));
        const rightGain = Math.max(0, gain(node.right));

        // Maximum path SUM passing through this node (uses both sides)
        const pathThroughNode = node.val + leftGain + rightGain;
        globalMax = Math.max(globalMax, pathThroughNode);

        // Return maximum ONE-SIDED gain to parent (parent can only extend one way)
        return node.val + Math.max(leftGain, rightGain);
    }

    gain(root);
    return globalMax;
}

// TRACE on [-10, 9, 20, null, null, 15, 7]:
//      -10
//      /  \
//     9   20
//        /  \
//       15   7
// gain(9):  left=0 right=0. path=9+0+0=9. globalMax=9. return 9.
// gain(15): left=0 right=0. path=15. globalMax=15. return 15.
// gain(7):  left=0 right=0. path=7. globalMax=15. return 7.
// gain(20): leftG=15 rightG=7. path=20+15+7=42. globalMax=42. return 20+15=35.
// gain(-10): leftG=9 rightG=35. path=-10+9+35=34. globalMax=42. return -10+35=25.
// Answer: 42 (path: 15->20->7)
console.log(maxPathSum(new TreeNode(-10,
    new TreeNode(9),
    new TreeNode(20, new TreeNode(15), new TreeNode(7))
))); // 42

