// RECURSIVE INORDER WITH EARLY EXIT — O(h+k) time
function kthSmallest(root, k) {
    let count = 0, result = null;
    function inorder(node) {
        if (!node || result !== null) return; // early exit when found
        inorder(node.left);
        count++;
        if (count === k) { result = node.val; return; }
        inorder(node.right);
    }
    inorder(root);
    return result;
}

// ITERATIVE INORDER — explicit stack, O(h) space
function kthSmallestIterative(root, k) {
    const stack = [];
    let curr = root;
    while (curr || stack.length) {
        // Go as far left as possible
        while (curr) { stack.push(curr); curr = curr.left; }
        curr = stack.pop();   // process next inorder node
        if (--k === 0) return curr.val; // found kth
        curr = curr.right;    // move to right subtree
    }
    return -1; // k > number of nodes
}

// BST ITERATOR — O(h) amortized per next(), O(h) space
class BSTIterator {
    constructor(root) {
        this.stack = [];
        this._pushLeft(root); // initialise stack with leftmost path
    }
    _pushLeft(node) {
        while (node) { this.stack.push(node); node = node.left; }
    }
    next() {
        const node = this.stack.pop();   // leftmost unprocessed
        this._pushLeft(node.right);       // prepare right subtree's leftmost path
        return node.val;
    }
    hasNext() { return this.stack.length > 0; }
}
// next() is O(h) amortized: each node pushed and popped at most once
// Space: O(h) — only current leftmost path is on the stack

