class TrieNode {
    constructor() {
        this.children = new Map(); // char -> TrieNode
        this.isEnd = false;         // true if a word ends here
    }
}

class Trie {
    constructor() {
        this.root = new TrieNode();
    }

    // INSERT — O(m) where m = word.length
    insert(word) {
        let node = this.root;
        for (const char of word) {
            if (!node.children.has(char)) {
                node.children.set(char, new TrieNode());
            }
            node = node.children.get(char);
        }
        node.isEnd = true; // mark end of word
    }

    // SEARCH — exact word match, O(m)
    search(word) {
        let node = this.root;
        for (const char of word) {
            if (!node.children.has(char)) return false; // char not found
            node = node.children.get(char);
        }
        return node.isEnd; // must be a complete word, not just a prefix
    }

    // STARTSWITH — prefix match, O(m)
    startsWith(prefix) {
        let node = this.root;
        for (const char of prefix) {
            if (!node.children.has(char)) return false;
            node = node.children.get(char);
        }
        return true; // any reachable path is a valid prefix
    }
}

