// AUTOCOMPLETE: collect all words with given prefix
class TrieWithAutocomplete extends Trie {
    getWordsWithPrefix(prefix) {
        // Step 1: navigate to prefix endpoint
        let node = this.root;
        for (const char of prefix) {
            if (!node.children.has(char)) return []; // prefix not found
            node = node.children.get(char);
        }
        // Step 2: DFS from prefix endpoint, collect all complete words
        const results = [];
        function dfs(curr, currentWord) {
            if (curr.isEnd) results.push(currentWord); // complete word found
            for (const [char, child] of curr.children) {
                dfs(child, currentWord + char); // extend word with char
            }
        }
        dfs(node, prefix);
        return results;
    }
}

