// DESIGN ADD AND SEARCH WORDS — wildcard '.' matches any char
class WordDictionary {
    constructor() { this.root = new TrieNode(); }

    addWord(word) {
        let node = this.root;
        for (const char of word) {
            if (!node.children.has(char)) node.children.set(char, new TrieNode());
            node = node.children.get(char);
        }
        node.isEnd = true;
    }

    search(word) {
        return this._dfs(this.root, word, 0);
    }

    _dfs(node, word, i) {
        if (i === word.length) return node.isEnd;  // consumed all chars
        const char = word[i];
        if (char === '.') {
            // Wildcard: try ALL children
            for (const child of node.children.values()) {
                if (this._dfs(child, word, i + 1)) return true;
            }
            return false;
        } else {
            // Exact match: follow single child
            if (!node.children.has(char)) return false;
            return this._dfs(node.children.get(char), word, i + 1);
        }
    }
}

