function findWords(board, words) {
    // Step 1: Build Trie from word list
    const root = new TrieNode();
    for (const word of words) {
        let node = root;
        for (const char of word) {
            if (!node.children.has(char)) node.children.set(char, new TrieNode());
            node = node.children.get(char);
        }
        node.isEnd = word; // store word string for easy retrieval
    }

    const m = board.length, n = board[0].length;
    const result = [];
    const DIRS = [[0,1],[0,-1],[1,0],[-1,0]];

    function dfs(row, col, trieNode) {
        const char = board[row][col];
        if (!trieNode.children.has(char)) return; // prefix mismatch: prune

        const nextNode = trieNode.children.get(char);

        if (nextNode.isEnd) {
            result.push(nextNode.isEnd);  // isEnd stores the word string
            nextNode.isEnd = false;        // PRUNE: don't add same word twice
        }

        board[row][col] = '#'; // mark visited (in-place, no extra set)
        for (const [dr, dc] of DIRS) {
            const r = row + dr, c = col + dc;
            if (r >= 0 && r < m && c >= 0 && c < n && board[r][c] !== '#') {
                dfs(r, c, nextNode);
            }
        }
        board[row][col] = char; // restore for other paths (backtrack)

        // PRUNE: remove leaf trie nodes after all searches from this node
        if (nextNode.children.size === 0) {
            trieNode.children.delete(char);
        }
    }

    // Step 2: Start DFS from every cell
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            dfs(r, c, root);
        }
    }
    return result;
}

