// Used by: hasPathSum, goodNodes, BST validation (bounds)
function topDownDFS(root, accumulatedState) {
    if (!root) return /* base result */0;
    const currentResult = /* check node against accumulatedState */0;
    const newState = /* update state for children */accumulatedState;
    return currentResult +
           topDownDFS(root.left,  newState) +
           topDownDFS(root.right, newState);
