function classifyM8Pattern(signals) {
  const s = new Set(signals);
  if (s.has('lca')||s.has('lowest_common_ancestor')) return 'LCA';
  if (s.has('right_side_view')||s.has('count_good')||s.has('good_nodes')) return 'View/Count DFS';
  if (s.has('serialize')||s.has('max_path_sum')||s.has('path_sum')) return 'Serialize/PathSum';
  if (s.has('kth_smallest')||s.has('bst_inorder')) return 'BST Inorder';
  if (s.has('trie')||s.has('prefix_search')||s.has('autocomplete')||s.has('word_search')) return 'Trie';
  return 'Unknown';
}

function solveLCA(root, p, q) {
  if (!root) return null;
  if (root === p || root === q) return root;
  const left = solveLCA(root.left, p, q);
  const right = solveLCA(root.right, p, q);
  if (left && right) return root;
  return left || right;
}

function solveMaxPathSum(root) {
  let globalMax = -Infinity;
  function gain(node) {
    if (!node) return 0;
    const l = Math.max(0, gain(node.left));
    const r = Math.max(0, gain(node.right));
    globalMax = Math.max(globalMax, node.val + l + r);
    return node.val + Math.max(l, r);
  }
  gain(root);
  return globalMax;
}

function solveTrieSearch(words, queryWord) {
  const root = new TrieNode();
  for (const w of words) {
    let n = root;
    for (const c of w) { if (!n.children.has(c)) n.children.set(c, new TrieNode()); n = n.children.get(c); }
    n.isEnd = true;
  }
  let n = root;
  for (const c of queryWord) { if (!n.children.has(c)) return false; n = n.children.get(c); }
  return n.isEnd;
}

function moduleCapabilitySummary() {
  const n1=new TreeNode(1),n2=new TreeNode(2),n3=new TreeNode(3);
  n1.left=n2; n1.right=n3;
  return {
    lca: solveLCA(n1,n2,n3) === n1,
    maxPathSum: solveMaxPathSum(new TreeNode(1,new TreeNode(2),new TreeNode(3))) === 6,
    trie: solveTrieSearch(['hello','world'],'hello') === true,
    trieNeg: solveTrieSearch(['hello'],'hell') === false
  };
}
